// Áreas de trabalho (workspaces) onde procurar os modelos e relatórios: o "Meu workspace" e as que o
// dono pode ver no Power BI (no máximo 30, para a consulta não demorar).
const grupos = Array.isArray($input.first().json.value) ? $input.first().json.value : [];
return [
  { json: { grupo_id: '', area: 'Meu workspace' } },
  ...grupos.slice(0, 30).map((g) => ({ json: { grupo_id: String(g.id ?? ''), area: String(g.name ?? '') } })),
];

// Junta os modelos semânticos (datasets) e relatórios de todas as áreas de trabalho e decide o que fazer:
// listar tudo, ou achar o modelo pedido (pelo nome do modelo ou do relatório) e montar a consulta DAX.
const pedido = $('Quando a Kira consultar o Power BI').first().json;
const areas = $('Áreas de trabalho').all().map((i) => i.json);
const modelosPorArea = $('Listar modelos').all().map((i) => i.json);
const relatoriosPorArea = $('Listar relatórios').all().map((i) => i.json);

const semAcento = (s) =>
  String(s ?? '')
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
const TIPOS = {
  listar: 'listar', lista: 'listar', modelos: 'listar', relatorios: 'listar', paineis: 'listar',
  estrutura: 'estrutura', tabelas: 'estrutura', colunas: 'estrutura', campos: 'estrutura',
  consulta: 'consulta', consultar: 'consulta', dax: 'consulta', dados: 'consulta',
};
const tipo = TIPOS[semAcento(pedido.tipo || 'listar')] || 'listar';

// Alguns nomes vêm codificados como em endereço de internet ("Relat%C3%B3rio").
const nomeLegivel = (s) => {
  const t = String(s ?? '');
  try {
    return /%[0-9a-f]{2}/i.test(t) ? decodeURIComponent(t) : t;
  } catch (e) {
    return t;
  }
};

// Catálogo: cada modelo com a área e os relatórios que usam ele.
const modelos = [];
const relatorios = [];
areas.forEach((area, i) => {
  for (const d of modelosPorArea[i]?.value ?? []) {
    if (!d?.id || modelos.some((m) => m.id === d.id)) continue;
    modelos.push({ id: String(d.id), nome: nomeLegivel(d.name), area: area.area, grupo_id: area.grupo_id, relatorios: [] });
  }
  for (const r of relatoriosPorArea[i]?.value ?? []) {
    if (r?.datasetId) relatorios.push({ nome: nomeLegivel(r.name), modelo_id: String(r.datasetId) });
  }
});
// Relatórios compartilhados com o dono cujo modelo fica numa área de trabalho em que ele não está: o modelo
// entra no catálogo com o nome do relatório e é consultado pelo endereço geral de modelos.
for (const r of relatorios) {
  let m = modelos.find((x) => x.id === r.modelo_id);
  if (!m) {
    m = { id: r.modelo_id, nome: r.nome, area: 'compartilhado com você', grupo_id: '', relatorios: [] };
    modelos.push(m);
  }
  if (!m.relatorios.includes(r.nome)) m.relatorios.push(r.nome);
}
const semAcesso = areas.filter((a, i) => modelosPorArea[i]?.error).map((a) => a.area);
const resumo = (m) => ({ modelo: m.nome, area: m.area, relatorios: m.relatorios.slice(0, 10) });

const responder = (resposta) => [{ json: { consultar: false, resposta } }];
if (tipo === 'listar') {
  return responder({
    ok: true,
    tipo,
    total: modelos.length,
    modelos: modelos.slice(0, 60).map(resumo),
    ...(semAcesso.length ? { areas_sem_acesso: semAcesso } : {}),
    orientacao: modelos.length
      ? 'Para consultar, use tipo "estrutura" com o nome do modelo (ou do relatório) e depois tipo "consulta" com uma consulta DAX.'
      : 'Nenhum modelo encontrado: o dono precisa ter acesso (com permissão de criar conteúdo) a algum modelo no Power BI.',
  });
}

const busca = semAcento(pedido.modelo);
if (!busca) return responder({ ok: false, tipo, erro: 'Faltou dizer qual modelo (ou relatório) consultar.', modelos: modelos.map(resumo) });
const porNome = (m) => [m.nome, ...m.relatorios].map(semAcento);
const modelo =
  modelos.find((m) => m.id === String(pedido.modelo).trim()) ||
  modelos.find((m) => porNome(m).includes(busca)) ||
  modelos.find((m) => porNome(m).some((n) => n.includes(busca) || (n && busca.includes(n))));
if (!modelo) {
  return responder({ ok: false, tipo, erro: `Não achei no Power BI um modelo ou relatório com "${pedido.modelo}".`, modelos: modelos.slice(0, 60).map(resumo) });
}

let dax;
if (tipo === 'estrutura') {
  dax = 'EVALUATE COLUMNSTATISTICS()';
} else {
  dax = String(pedido.dax ?? '').trim();
  if (!/^(DEFINE|EVALUATE)\b/i.test(dax)) {
    return responder({
      ok: false,
      tipo,
      modelo: modelo.nome,
      erro: 'A consulta precisa ser DAX e começar com EVALUATE (ou DEFINE).',
      orientacao: 'Veja as tabelas e colunas com tipo "estrutura" e escreva, por exemplo: EVALUATE TOPN(20, SUMMARIZECOLUMNS(Tabela[Coluna], "Total", SUM(Tabela[Valor])), [Total], DESC)',
    });
  }
}
const limite = Math.min(Math.max(Math.round(Number(pedido.limite) || 50), 1), 200);
const base = (modelo.grupo_id ? `https://api.powerbi.com/v1.0/myorg/groups/${modelo.grupo_id}` : 'https://api.powerbi.com/v1.0/myorg') + `/datasets/${modelo.id}`;
return [{ json: { consultar: true, tipo, modelo: { nome: modelo.nome, area: modelo.area, relatorios: modelo.relatorios }, base, dax, limite } }];

// Monta a resposta para a Kira: a estrutura do modelo (tabelas, colunas e medidas) ou as linhas da consulta,
// com a hora da última atualização do modelo. Erros do Power BI viram uma explicação curta.
const escolha = $('Escolher modelo').first().json;
if (!escolha.consultar) return [{ json: escolha.resposta }];

const resposta = $('Executar DAX').first().json;
const corpo = resposta.body ?? resposta;
const status = Number(resposta.statusCode) || (corpo?.error ? 400 : 200);
const base = { tipo: escolha.tipo, modelo: escolha.modelo.nome, area: escolha.modelo.area };

// Hora da última atualização do modelo (horário de Brasília).
const atualizacao = $('Última atualização').isExecuted ? $('Última atualização').first().json?.value?.[0] : null;
const quando = atualizacao?.endTime || atualizacao?.startTime;
if (quando) {
  const local = new Date(Date.parse(quando) - 3 * 3600000).toISOString();
  base.atualizado_em = `${local.slice(8, 10)}/${local.slice(5, 7)}/${local.slice(0, 4)} às ${local.slice(11, 16)}`;
  if (atualizacao.status && atualizacao.status !== 'Completed') base.ultima_atualizacao = atualizacao.status;
}

const detalhe = (c) => {
  const pbi = c?.error?.['pbi.error'];
  const msg = (pbi?.details ?? []).find((d) => /message/i.test(d.code ?? ''))?.detail?.value;
  return String(msg || c?.error?.message || c?.error?.code || c?.message || '').slice(0, 400);
};
if (status >= 400 || corpo?.error) {
  const semPermissao =
    status === 401 || status === 403 || (status === 404 && /PowerBIEntityNotFound|required permissions/i.test(JSON.stringify(corpo ?? '')));
  if (semPermissao) {
    return [{
      json: {
        ok: false,
        ...base,
        erro: 'A conta conectada ao Power BI pode ver este relatório, mas não tem permissão para consultar os dados dele pela API.',
        orientacao: 'Explique ao dono que quem administra este Power BI (o dono do modelo ou o administrador da área de trabalho) precisa dar à conta conectada na Kira a permissão de criar conteúdo (Build) no modelo semântico deste relatório; sem isso, você não consegue ler esses dados. Não invente números.',
      },
    }];
  }
  return [{ json: { ok: false, ...base, erro: `A consulta DAX deu erro: ${detalhe(corpo) || `HTTP ${status}`}`, orientacao: 'Corrija a consulta (use os nomes de tabelas e colunas da estrutura) e tente de novo; se não der, explique ao dono.' } }];
}

const linhas = corpo?.results?.[0]?.tables?.[0]?.rows ?? [];
// "Tabela[Coluna]" ou "[Coluna]" -> "Coluna" (se repetir, fica o nome completo)
const limparChaves = (linha) => {
  const saida = {};
  for (const [k, v] of Object.entries(linha)) {
    const curto = (/\[([^\]]+)\]$/.exec(k) || [])[1] || k;
    saida[curto in saida ? k : curto] = typeof v === 'string' && v.length > 300 ? v.slice(0, 299) + '…' : v;
  }
  return saida;
};

if (escolha.tipo === 'estrutura') {
  const tabelas = {};
  for (const l of linhas.map(limparChaves)) {
    const tabela = String(l['Table Name'] ?? '');
    const coluna = String(l['Column Name'] ?? '');
    if (!tabela || /^(DateTableTemplate_|LocalDateTable_)/.test(tabela) || /^RowNumber-/.test(coluna)) continue;
    (tabelas[tabela] ??= []).push(coluna);
  }
  const medidas = {};
  const respostaMedidas = $('Listar medidas').isExecuted ? $('Listar medidas').first().json : null;
  const linhasMedidas = (respostaMedidas?.body ?? respostaMedidas)?.results?.[0]?.tables?.[0]?.rows ?? [];
  for (const l of linhasMedidas.map(limparChaves)) {
    if (l.Medida) (medidas[String(l.Tabela ?? '')] ??= []).push(String(l.Medida));
  }
  return [{
    json: {
      ok: true,
      ...base,
      tabelas: Object.fromEntries(Object.entries(tabelas).slice(0, 40).map(([t, cols]) => [t, cols.slice(0, 200)])),
      ...(Object.keys(medidas).length ? { medidas } : { medidas: 'não disponíveis (use as colunas com SUM, COUNTROWS etc.)' }),
      orientacao: 'Escreva a consulta DAX com esses nomes, por exemplo: EVALUATE TOPN(20, SUMMARIZECOLUMNS(Tabela[Coluna], "Total", [Medida]), [Total], DESC). Nomes com espaço ficam entre aspas simples: \'Minha Tabela\'[Coluna].',
    },
  }];
}

const dados = linhas.slice(0, escolha.limite).map(limparChaves);
return [{
  json: {
    ok: true,
    ...base,
    linhas: dados.length,
    total_linhas: linhas.length,
    ...(linhas.length > dados.length ? { cortado: `mostrando ${dados.length} de ${linhas.length} linhas` } : {}),
    dados,
  },
}];

// Falha ao listar as áreas de trabalho do Power BI: quase sempre é a credencial.
const erro = $input.first().json.error ?? $input.first().json;
const texto = String(erro?.message ?? erro?.description ?? erro ?? '').slice(0, 300);
let orientacao = 'Explique ao dono, em uma frase, que o Power BI não respondeu agora e sugira tentar de novo em alguns minutos.';
if (/401|403|unauthori[sz]ed|forbidden|credential|token|consent|invalid_grant/i.test(texto)) {
  orientacao = 'Diga ao dono que a conexão com o Power BI precisa ser refeita: no n8n, em Credentials, abrir a credencial "Power BI (Kira)" e clicar em reconectar.';
}
return [{ json: { ok: false, erro: `Não consegui acessar o Power BI: ${texto || 'sem detalhe'}`, orientacao } }];
